17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.Map;
25	import java.util.regex.Pattern;
26	
27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
36	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
37	import org.springframework.samples.petclinic.mapper.MembershipLevel;
38	import org.springframework.samples.petclinic.mapper.OwnerLocality;
39	import org.springframework.samples.petclinic.mapper.OwnerMapper;
40	import org.springframework.samples.petclinic.mapper.PetMapper;
41	import org.springframework.samples.petclinic.mapper.VisitMapper;
42	import org.springframework.samples.petclinic.model.Owner;
43	import org.springframework.samples.petclinic.model.Pet;
44	import org.springframework.samples.petclinic.model.Visit;
45	import org.springframework.samples.petclinic.rest.api.OwnersApi;
46	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
47	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.PetDto;
49	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
52	import org.springframework.samples.petclinic.service.ClinicService;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.util.StringUtils;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
73	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
74	     * addresses are lower-cased before being stored.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** An owner's postcode, when supplied, must be exactly four digits. */
80	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
81	
82	    /**
83	     * Region -> inclusive 4-digit postcode range {low, high}. A postcode supplied for an owner whose
84	     * city maps (via {@link OwnerLocality#forCity}) to one of these regions must fall within the
85	     * region's range; a city with no known region ("UNKNOWN") accepts any 4-digit postcode.
86	     */
87	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
88	        "NSW", new int[] {2000, 2099},
89	        "VIC", new int[] {3000, 3099},
90	        "QLD", new int[] {4000, 4099});
91	
92	    /**
93	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
94	     * named logger keeps them addressable independently of the class's diagnostic logging.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    /**
99	     * Maximum number of owners a single city may contain. A create that would take the owner's city
100	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
101	     */
102	    private static final int CITY_OWNER_LIMIT = 50;
103	
104	    /**
105	     * Maximum number of owners that may be registered on a single day. A create that would take the
106	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
107	     * have already been created that day - is rejected with a 429.
108	     */
109	    private static final int DAILY_OWNER_LIMIT = 100;
110	
111	    /**
112	     * Number of owners that must already have been created for a given day before the create
113	     * response flags a bulk sign-up. When more than this many owners already share a
114	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
115	     */
116	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
117	
118	    private final ClinicService clinicService;
119	
120	    private final OwnerMapper ownerMapper;
121	
122	    private final PetMapper petMapper;
123	
124	    private final VisitMapper visitMapper;
125	
126	    public OwnerRestControllerV1(ClinicService clinicService,
127	                                 OwnerMapper ownerMapper,
128	                                 PetMapper petMapper,
129	                                 VisitMapper visitMapper) {
130	        this.clinicService = clinicService;
131	        this.ownerMapper = ownerMapper;
132	        this.petMapper = petMapper;
133	        this.visitMapper = visitMapper;
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
139	        Collection<Owner> owners;
140	        if (lastName != null) {
141	            owners = this.clinicService.findOwnerByLastName(lastName);
142	        } else {
143	            owners = this.clinicService.findAllOwners();
144	        }
145	        if (owners.isEmpty()) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
159	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
160	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
161	    }
162	
163	    /**
164	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
165	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
166	     * owner sign-ups.
167	     *
168	     * @param registrationDate the day to inspect, or {@code null}
169	     * @return {@code true} when more than the threshold of owners are registered on that day
170	     */
171	    private boolean isBulkSignupDay(LocalDate registrationDate) {
172	        return registrationDate != null
173	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
179	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
180	        validateRequiredFields(ownerFieldsDto);
181	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
182	        HttpHeaders headers = new HttpHeaders();
183	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
184	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
185	        owner.setEmail(normalizeEmail(owner.getEmail()));
186	        if (owner.getRegistrationDate() == null) {
187	            owner.setRegistrationDate(LocalDate.now());
188	        }
189	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
190	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
191	        owner.setIdentityKey(buildIdentityKey(owner,
192	            Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())));
193	        rejectDuplicateOwner(owner.getIdentityKey());
194	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
195	            throw new OwnerCityFullException(owner.getCity());
196	        }
197	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
198	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
199	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
200	        }
201	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
202	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
203	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
204	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
205	        this.clinicService.saveOwner(owner);
206	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
207	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
208	            MembershipLevel.forOwner(owner));
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
210	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
211	        headers.setLocation(UriComponentsBuilder.newInstance()
212	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
213	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
214	    }
215	
216	    /**
217	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
218	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
219	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
220	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
221	     * after normalization is still rejected.
222	     *
223	     * @param ownerFieldsDto the submitted owner fields
224	     */
225	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
226	        List<String> missingFields = new ArrayList<>();
227	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
228	            missingFields.add("firstName");
229	        }
230	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
231	            missingFields.add("lastName");
232	        }
233	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
234	            missingFields.add("address");
235	        }
236	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
237	            missingFields.add("city");
238	        }
239	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
240	            missingFields.add("telephone");
241	        }
242	        if (!missingFields.isEmpty()) {
243	            throw new MissingOwnerFieldsException(missingFields);
244	        }
245	    }
246	
247	    /**
248	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
249	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
250	     * city maps to a known region (via {@link OwnerLocality#forCity}) the postcode must fall within that
251	     * region's inclusive range ({@link #REGION_POSTCODE_RANGES}). A city with no known region accepts any
252	     * 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400 whose {@code errors}
253	     * array lists {@code postcode}.
254	     *
255	     * @param postcode the submitted postcode, or {@code null} when none was supplied
256	     * @param city the owner's city, whose region determines the acceptable postcode range
257	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
258	     */
259	    private void validatePostcode(String postcode, String city) {
260	        if (!StringUtils.hasText(postcode)) {
261	            return;
262	        }
263	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
264	            throw new InvalidOwnerFieldsException(List.of("postcode"));
265	        }
266	        int[] range = REGION_POSTCODE_RANGES.get(OwnerLocality.forCity(city));
267	        if (range != null) {
268	            int value = Integer.parseInt(postcode);
269	            if (value < range[0] || value > range[1]) {
270	                throw new InvalidOwnerFieldsException(List.of("postcode"));
271	            }
272	        }
273	    }
274	
275	    /**
276	     * Rejects a submitted owner whose derived {@code identityKey} exactly matches an existing owner's.
277	     * All duplicate detection is consolidated into this single key, so a collision is reported to the
278	     * client as a 409 Conflict regardless of which field(s) coincide. Because the telephone is part of
279	     * the key, two owners that differ in telephone can never collide even when they share every other
280	     * component (for example two members of the same household).
281	     *
282	     * @param identityKey the derived identity key of the owner about to be created
283	     */
284	    private void rejectDuplicateOwner(String identityKey) {
285	        boolean duplicate = this.clinicService.findAllOwners().stream()
286	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
287	        if (duplicate) {
288	            throw new DuplicateOwnerIdentityException(identityKey);
289	        }
290	    }
291	
292	    /**
293	     * Derives the owner's {@code identityKey}, the single value through which all duplicate detection is
294	     * expressed. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
295	     * where the telephone and email have already been normalized. The household segment carries the
296	     * owner's {@code householdId} only when the owner knowingly belongs to a shared household (the
297	     * request opted in with {@code sharesHousehold}); otherwise it is empty, so an owner is identified
298	     * by telephone and email alone.
299	     *
300	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
301	     * @param sharesHousehold whether the request opted into a shared household
302	     * @return the derived identity key
303	     */
304	    private String buildIdentityKey(Owner owner, boolean sharesHousehold) {
305	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
306	        String household = sharesHousehold ? owner.getHouseholdId() : "";
307	        return owner.getTelephone() + "|" + email + "|" + household;
308	    }
309	
310	    /**
311	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
312	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
313	     * address; the accepted value is lower-cased before it is stored and returned.
314	     *
315	     * @param email the raw email value submitted by the client, or {@code null}
316	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
317	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
318	     */
319	    private String normalizeEmail(String email) {
320	        if (!StringUtils.hasText(email)) {
321	            return email;
322	        }
323	        if (!EMAIL_PATTERN.matcher(email).matches()) {
324	            throw new InvalidOwnerFieldsException(List.of("email"));
325	        }
326	        return email.toLowerCase();
327	    }
328	
329	    /**
330	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
331	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
332	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
333	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
334	     *
335	     * @param city the owner's city
336	     * @param lastName the owner's last name
337	     * @return the assigned customer code
338	     */
339	    private String buildCustomerCode(String city, String lastName) {
340	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
341	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
342	        int sequence = (int) this.clinicService.findAllOwners().stream()
343	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
344	            .count() + 1;
345	        return String.format("%s-%s-%04d", city3, last3, sequence);
346	    }
347	
348	    /**
349	     * Counts how many owners already exist that share the supplied first and last name, compared
350	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
351	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
352	     *
353	     * @param firstName the submitted owner's first name
354	     * @param lastName the submitted owner's last name
355	     * @return the number of existing owners with the same first and last name, ignoring case
356	     */
357	    private int countNamesakes(String firstName, String lastName) {
358	        return (int) this.clinicService.findAllOwners().stream()
359	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
360	                && lastName.equalsIgnoreCase(existing.getLastName()))
361	            .count();
362	    }
363	
364	    /**
365	     * Counts how many existing owners already belong to the supplied household, identified by its
366	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
367	     * owner is added (this count plus one).
368	     *
369	     * @param householdId the normalized household identifier of the owner being created
370	     * @return the number of existing owners already sharing that {@code householdId}
371	     */
372	    private int countHouseholdMembers(String householdId) {
373	        return (int) this.clinicService.findAllOwners().stream()
374	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
375	            .count();
376	    }
377	
378	    /**
379	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
380	     * enforce the per-city capacity limit when a new owner is created.
381	     *
382	     * @param city the submitted owner's city
383	     * @return the number of existing owners in that city, ignoring case
384	     */
385	    private long countOwnersInCity(String city) {
386	        return this.clinicService.findAllOwners().stream()
387	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
388	            .count();
389	    }
390	
391	    /**
392	     * Counts how many owners have already been created on the supplied registration date. Used to
393	     * enforce the per-day capacity limit when a new owner is created.
394	     *
395	     * @param registrationDate the registration date of the owner being created
396	     * @return the number of existing owners already registered on that date
397	     */
398	    /**
399	     * Rolls a registration date forward to a business day. A registration date must fall on a
400	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
401	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
402	     * from the registration date (such as the membership number's year segment) and the daily
403	     * create-limit therefore use the adjusted date.
404	     *
405	     * @param date the effective registration date, whether supplied or defaulted to the server date
406	     * @return the same date when it is a weekday, otherwise the next Monday
407	     */
408	    private LocalDate toBusinessDay(LocalDate date) {
409	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
410	            date = date.plusDays(1);
411	        }
412	        return date;
413	    }
414	
415	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
416	        return this.clinicService.findAllOwners().stream()
417	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
418	            .count();
419	    }
420	
421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Override
423	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
424	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
425	        if (currentOwner == null) {
426	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
427	        }
428	        currentOwner.setAddress(ownerFieldsDto.getAddress());
429	        currentOwner.setCity(ownerFieldsDto.getCity());
430	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
431	        currentOwner.setLastName(ownerFieldsDto.getLastName());
432	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
433	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
434	        this.clinicService.saveOwner(currentOwner);
435	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Transactional
440	    @Override
441	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
442	        Owner owner = this.clinicService.findOwnerById(ownerId);
443	        if (owner == null) {
444	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
445	        }
446	        this.clinicService.deleteOwner(owner);
447	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
448	    }
449	
450	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
451	    @Override
452	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
453	        Owner owner = this.clinicService.findOwnerById(ownerId);
454	        if (owner == null) {
455	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
456	        }
457	        HttpHeaders headers = new HttpHeaders();
458	        Pet pet = petMapper.toPet(petFieldsDto);
459	        owner.setId(ownerId);
460	        pet.setOwner(owner);
461	        pet.getType().setName(null);
462	        this.clinicService.savePet(pet);
463	        PetDto petDto = petMapper.toPetDto(pet);
464	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
465	            .buildAndExpand(pet.getId()).toUri());
466	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
467	    }
468	
469	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
470	    @Override
471	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
472	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
473	        if (currentOwner != null) {
474	            Pet currentPet = this.clinicService.findPetById(petId);
475	            if (currentPet != null) {
476	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
477	                currentPet.setName(petFieldsDto.getName());
478	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
479	                this.clinicService.savePet(currentPet);
480	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
481	            }
482	        }
483	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
484	    }
485	
486	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
487	    @Override
488	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
489	        HttpHeaders headers = new HttpHeaders();
490	        Visit visit = visitMapper.toVisit(visitFieldsDto);
491	        Pet pet = new Pet();
492	        pet.setId(petId);
493	        visit.setPet(pet);
494	        this.clinicService.saveVisit(visit);
495	        VisitDto visitDto = visitMapper.toVisitDto(visit);
496	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
497	            .buildAndExpand(visit.getId()).toUri());
498	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
499	    }
500	
501	
502	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
503	    @Override
504	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
505	        Owner owner = this.clinicService.findOwnerById(ownerId);
506	        if (owner != null) {
507	            Pet pet = owner.getPet(petId);
508	            if (pet != null) {
509	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
510	            }
511	        }
512	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
513	    }
514	}
