1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region), preferring the postcode: the region is
7	 * looked up by postcode range first, and only when the postcode is absent or in
8	 * no known range does it fall back to a fixed city-to-region table. This returns
9	 * the same region for the known cities but disambiguates cities that share a name.
10	 *
11	 * <p>Kept as a plain static helper - rather than a method on {@link OwnerMapper} -
12	 * so MapStruct does not mistake it for an implicit String-to-String property
13	 * mapping and apply it to unrelated fields.
14	 *
15	 * <p>Public, like its sibling {@link MembershipLevel}, so the single region table
16	 * can be reused wherever an owner's region is needed rather than being
17	 * duplicated - callers outside this package derive the region through
18	 * {@link #forPostcodeAndCity(String, String)} (or {@link #forCity(String)} when
19	 * only the city is available) instead of holding their own copy of the tables.
20	 */
21	public final class OwnerLocality {
22	
23	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
24	    private static final Map<String, String> CITY_REGION = Map.of(
25	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
26	
27	    /** Region -> inclusive 4-digit postcode range {low, high}. */
28	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
29	        "NSW", new int[] {2000, 2099},
30	        "VIC", new int[] {3000, 3099},
31	        "QLD", new int[] {4000, 4099});
32	
33	    private OwnerLocality() {
34	    }
35	
36	    /**
37	     * Returns the canonical region for the given owner, preferring the postcode:
38	     * the region is derived from the postcode range first, falling back to the
39	     * city-to-region table only when the postcode is absent or in no known range.
40	     *
41	     * @param postcode the owner's postcode, or {@code null} when none was supplied
42	     * @param city the owner's city
43	     * @return the derived locality (region)
44	     */
45	    public static String forPostcodeAndCity(String postcode, String city) {
46	        String region = forPostcode(postcode);
47	        return region != null ? region : forCity(city);
48	    }
49	
50	    /**
51	     * Returns the canonical region for the given city, or "UNKNOWN" when the city
52	     * is not in the fixed table (or is {@code null}).
53	     *
54	     * @param city the owner's city
55	     * @return the derived locality (region)
56	     */
57	    public static String forCity(String city) {
58	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
59	    }
60	
61	    /**
62	     * Returns the region whose postcode range contains the given postcode, or
63	     * {@code null} when the postcode is missing, non-numeric or in no known range.
64	     */
65	    private static String forPostcode(String postcode) {
66	        if (postcode == null) {
67	            return null;
68	        }
69	        int value;
70	        try {
71	            value = Integer.parseInt(postcode.trim());
72	        }
73	        catch (NumberFormatException e) {
74	            return null;
75	        }
76	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
77	            int[] range = entry.getValue();
78	            if (value >= range[0] && value <= range[1]) {
79	                return entry.getKey();
80	            }
81	        }
82	        return null;
83	    }
84	
85	}
