24	/**
25	 * Normalizes a submitted telephone number into the canonical form that is stored for an owner and
26	 * compared when detecting duplicate telephones. Kept apart from {@link OwnerRestControllerV1} so the
27	 * request handler stays focused on orchestration while the rules for what makes a telephone
28	 * acceptable, and how it is canonicalized, live in one place.
29	 *
30	 * <p>The rule canonicalizes to E.164: spaces, dashes and brackets are stripped; a leading '+' with a
31	 * country code is kept as-is, otherwise country code '+61' is assumed and a single leading '0' is
32	 * dropped from the national digits. The result must be a '+' followed by 8 to 15 digits. That '+' and
33	 * digit string is what gets stored and returned.
34	 *
35	 * <p>For the country codes with a known fixed-length numbering plan the national number (the digits
36	 * that follow the country code) must additionally be exactly the expected length: '+61' (Australia)
37	 * requires 9 national digits and '+1' (NANP) requires 10. A value whose national-number length is
38	 * wrong for its country is rejected as an invalid telephone.
39	 */
40	final class TelephoneNormalizer {
41	
42	    /**
43	     * Country codes (including the leading '+') whose numbering plan fixes the national-number length,
44	     * mapped to that required number of national digits. A normalized number beginning with one of
45	     * these country codes must carry exactly this many digits after the country code. Country codes
46	     * absent from this map are not length-checked beyond the general 8-to-15 digit E.164 bound.
47	     */
48	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
49	        "+61", 9,
50	        "+1", 10);
51	
52	    private TelephoneNormalizer() {
53	    }
54	
55	    /**
56	     * Normalizes a raw telephone value for owner creation into E.164 form. The normalized value is both
57	     * what gets stored and what duplicate detection compares against, so two inputs that canonicalize to
58	     * the same value are treated as the same telephone.
59	     *
60	     * <p>Spaces, dashes and brackets are removed. A value beginning with '+' keeps its leading '+' and
61	     * country code; any other value assumes country code '+61' and drops a single leading '0' from the
62	     * national digits. The result must be a '+' followed by 8 to 15 digits.
63	     *
64	     * @param telephone the raw telephone value submitted by the client
65	     * @return the normalized E.164 telephone number (a '+' followed by 8 to 15 digits)
66	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
67	     */
68	    static String normalize(String telephone) {
69	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]{}]", "");
70	
71	        String e164;
72	        if (cleaned.startsWith("+")) {
73	            e164 = "+" + cleaned.substring(1);
74	        }
75	        else {
76	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
77	            e164 = "+61" + national;
78	        }
79	
80	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
81	            throw new InvalidOwnerFieldsException(List.of("telephone"));
82	        }
83	        for (Map.Entry<String, Integer> plan : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
84	            String countryCode = plan.getKey();
85	            if (e164.startsWith(countryCode)) {
86	                int nationalLength = e164.length() - countryCode.length();
87	                if (nationalLength != plan.getValue()) {
88	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
89	                }
90	                break;
91	            }
92	        }
93	        return e164;
94	    }
95	
96	}
